from curated import add, profile

CDMP7000_REFERENCES={'Gemini CDMP-7000': {'url': 'https://raw.githubusercontent.com/djtrinidad/mixxx-gemini-cdmp7000-latest/3236e2380a1b24c662fc58777d266b21f9cc46ec/Gemini_CDMP-7000-test.midi.xml', 'sha256': 'd434a696726694f0bef4ff66cc836a5ee65c41c78e847d329ea10a59bf87b89d', 'upstreamRevision': '3236e2380a1b24c662fc58777d266b21f9cc46ec', 'files': [{'cachePath': 'TestBuilds/r475/upstream/cdmp7000.midi.xml', 'sha256': 'd434a696726694f0bef4ff66cc836a5ee65c41c78e847d329ea10a59bf87b89d'}, {'cachePath': 'TestBuilds/r475/upstream/cdmp7000-scripts.js', 'sha256': '8fb63dabbee403dca4d64ad9355a88239a4b61d4e073165940afc99e135e1a9b'}, {'cachePath': 'TestBuilds/r475/upstream/cdmp7000-readme.md', 'sha256': 'f87af6d775997b20c6d02a05c620cccb76b47a5aecf7ae2d7126eeaabed492b0'}, {'cachePath': 'TestBuilds/r475/upstream/cdmp7000-older-scripts.js', 'sha256': 'a15972ffe4ce3d4efc381e273afa0cd98c9a2263d97e3df3d1f43d1e47eb10cd'}], 'relatedSources': [{'url': 'https://github.com/djtrinidad/mixxx-gemini-cdmp7000-latest'}, {'url': 'https://raw.githubusercontent.com/djtrinidad/cdmp7000-mixxx/c4b2a1949e0623c8433471a8a6a42c582e57ba5f/gemini_CDMP-7000-scripts.js'}], 'review': 'Primary owner djtrinidad own-model XML and component mapper at3236e2380a1b24c662fc58777d266b21f9cc46ec identify CDMP-7000 Deck A and explicitly say the hardware exposes separate L/R units using the same file. Manual raw0 player core only. Separate endpoints remain manual target A; no unverified automatic endpoint identity, right-side mapping or hardware channel switch is inferred. Play02, held native Cue01, bend+/minus03/04, Select/Load0F and In10/Out11/Reloop12 are explicit. Note0B/0C are track-list previous/next pulses. PitchCC21 has an explicit invert option; copied FIX comment leaves physical polarity/range acceptance open. Native uses its existing +/-8percent range and pickup. JogCC20 uses value-minus64 and scratchEnable128 at33+1/3RPM; own earlier repository c4b2a1949e0623c8433471a8a6a42c582e57ba5f independently agrees on128. TouchNote18 uses native fixed touch scratch; hardware Vinyl button/state and source intermittent scratch bug are not imported. Relative count/calibration and live feel require hardware acceptance. The source MIDI0D is labelled Master Tempo and XML sync_leader despite an unused SyncButton object; it does not qualify native Sync toggle. LOCK1C is not proven Keylock. Memo08 is toggled in software with contradictory0x91 object and0x90 XML; all Hot Cues/clears stay inactive. Source duplicateNote25, empty FX keys/notes, LCD SysEx, reset loops, timers, slip/reverse/search, effects, full lamps and source lifecycle do not run. No analogue mixer control/audio route is inferred from the standalone mixer. README only reports CDJ-700 compatibility; no CDJ-700/CDJ650/CDMP2700/GMX/MDJ protocol or identity is inherited. Exact USB naming/channel choice/driver/OS/power/audio/DVS, full modes/lifecycle/recovery and physical/iPad/A10X acceptance remain open. Requires an existing CoreMIDI endpoint and separate app audio. No upstream source, mapper, driver, firmware, query, setup, hardware mode, preset, output or audio-route write executes or ships.'}}


def cdmp7000_profiles():
    """Return a manual raw0 normal player with fixed native touch scratch."""
    ref=CDMP7000_REFERENCES['Gemini CDMP-7000'];p=profile('Gemini CDMP-7000',ref['url'])
    p.update(definition='reviewed:cdmp7000-owner-raw0-player-core',role='player',autoSelect=False,
        aliases=['Gemini CDMP-7000','Gemini CDMP7000','CDMP-7000','CDMP7000'],
        excludedAliases=['CDJ-700','CDJ700','CDJ650','CDMP-2700','MDJ','GMX'],
        hardwareMode='Manual CDMP-7000 player endpoint, MIDI channel1/raw0. Target A. Expose its MIDI source and configure app audio separately. Fixed native touch scratch and native tempo range. Other endpoint assignment, Memo, Vinyl modes, mixer and screens remain unqualified.',
        scope='Manual13-input normal player: Play, held Cue/bends, Load, manual loops, directional track browse pulses, inverted absolute tempo and128-count touch scratch. No automatic identity, Sync/Keylock, pads, mixer, lights, LCD or audio-route claim.',gaps=[ref['review']])
    for action,n in [('play',2),('cuePreview',1),('pitchBendUp',3),('pitchBendDown',4),('load',15),('loopIn',16),('loopOut',17),('reloop',18)]:add(p,action,0,n,deck='a')
    for action,n in [('browsePrevious',11),('browseNext',12)]:
        add(p,action,0,n);p['inputs'][-1]['pulse']=True
    add(p,'tempo',0,33,'control',deck='a');p['inputs'][-1]['inverted']=True
    add(p,'jog',0,32,'control','binaryOffset','a');p['inputs'][-1]['argument']=128
    add(p,'jogTouch',0,24,deck='a')
    return [p]
